try:
    from string.templatelib import Template, Interpolation
except ImportError:  # sandbox Python < 3.14: minimal stand-ins that iterate like the real classes
    class Interpolation:
        def __init__(self, value, expression='', conversion=None, format_spec=''):
            self.value, self.expression = value, expression
            self.conversion, self.format_spec = conversion, format_spec
    class Template:
        def __init__(self, *args):
            self._items = [a for a in args if not (isinstance(a, str) and a == '')]
        def __iter__(self):
            return iter(self._items)
_r = render_upper(Template('Hello, ', Interpolation('world', 'name'), '!'))
assert _r == 'Hello, WORLD!', f'render_upper(t"Hello, {{name}}!") with name = "world" should return "Hello, WORLD!", got {_r!r}'
_r2 = render_upper(Template('Order ', Interpolation(42, 'n'), ' for ', Interpolation('ana', 'who'), ' is ready'))
assert _r2 == 'Order 42 for ANA is ready', f'Static text must stay unchanged and every interpolated value must be uppercased: expected "Order 42 for ANA is ready", got {_r2!r}'
